		return trace.Wrap(err)
	}
	if err := protocol.WritePreLoginResponse(conn); err != nil {
		return trace.Wrap(err)
	}
	if _, err := protocol.ReadLogin7Packet(conn); err != nil {
		return trace.Wrap(err)
	}
	if _, err := conn.Write(mockLoginServerResp); err != nil {
